<script setup lang="ts">
import {useParameterTransaction} from './useParameterTransaction';
import ParameterDialog from './ParameterDialog.vue';
const settingsOpen=ref(false);

import {ref,computed,watch,nextTick,onBeforeUnmount} from 'vue';import {apiError} from './apiError';import type {ECharts} from 'echarts/core';
const props=defineProps<{projectId:string}>();const emit=defineEmits<{task:[id:string]}>();const project=ref<any>(null);const engineering=ref<any>(null);const network=ref<any>(null);const error=ref('');const busy=ref(false);const history=ref<any[]>([]);const result=ref<any>(null);const hour=ref(0);let token=0;let drawToken=0;
const parameters=ref({name:'逐设备时序调度',start:'2026-01-01T00:00',steps:24,step_hours:1,grid_energy_yuan_per_kwh:.5,storage_cycle_yuan_per_kwh:.002,source_start_cost_yuan:.0001,grid_reactive_limit_kvar:0,branch_limit_kva:5000,voltage_min_pu:.95,voltage_max_pu:1.05,forming_reserve_ratio:.02,allow_demand_response:false,enforce_load_targets:false,include_candidates:false,time_limit_seconds:60});
const continuationEnabled=ref(false);
const continuationText=ref('{}');
const backgroundJob=ref('');
const grid=ref('0');const initial=ref('');const deviceSchedules=ref<{id:string;values:string}[]>([]);const lineSchedules=ref<{id:number;values:string}[]>([]);
const devices=computed(()=>engineering.value?['sources','storage','loads','transformers','switches'].flatMap(key=>engineering.value.inventory[key].map((a:any)=>({id:a.id,name:a.name}))):[]);
const snapshot=computed(()=>result.value?.result.rows[hour.value]);const chart=ref<HTMLElement>();let plot:ECharts|undefined;
const statusNames:Record<string,string>={passed:'满足',failed:'未满足',not_checked:'未完成校核',optimal:'分层目标已求解',feasible_limit:'达到时限，仅保留可行解'};
async function api(url:string,options?:RequestInit){const r=await fetch(url,options);const d=await r.json();if(!r.ok)throw Error(apiError(d.detail));return d}
async function refresh(){const current=++token;project.value=null;engineering.value=null;network.value=null;history.value=[];result.value=null;backgroundJob.value='';continuationEnabled.value=false;continuationText.value='{}';error.value='';deviceSchedules.value=[];lineSchedules.value=[];hour.value=0;busy.value=false;if(!props.projectId)return;try{const [p,e,h]=await Promise.all([api('/api/projects/'+props.projectId),api('/api/engineering/projects/'+props.projectId),api('/api/device-dispatch?project_id='+props.projectId)]);let n=p.state.network;if(!n)n=await api('/api/network/case33');if(current!==token)return;project.value=p;engineering.value=e;history.value=h;network.value=n}catch(e){if(current===token)error.value=String(e)}}
watch(()=>props.projectId,refresh,{immediate:true});
function series(text:string){if(!text.trim())throw Error('状态/容量曲线不能为空');const values=text.trim().split(/[,，\s]+/).map(Number);if(!values.every(Number.isFinite))throw Error('曲线须为有限数值');return values}
function keyed<T>(rows:{id:T;values:string}[]){const values:Record<string,number[]>={};for(const row of rows){if(values[String(row.id)])throw Error('同一设备/线路不能重复配置');values[String(row.id)]=series(row.values)}return values}
const continuationKeys = new Set([
 'start', 'step_hours', 'include_candidates', 'elapsed_hours', 'prior_target_history_complete', 'initial_state_provenance',
 'require_complete_target_horizon', 'load_target_start_hours',
 'initial_source_on', 'initial_source_power_kw', 'initial_source_startup_remaining_steps',
 'initial_source_fuel_kwh', 'initial_source_used_hours', 'initial_storage_energy_kwh',
 'initial_target_interruption_hours', 'initial_max_target_interruption_hours',
 'initial_total_target_interruption_hours', 'initial_energized_nodes',
 'source_energy_additions_kwh', 'source_forming_reserve_kwh',
]);
function continuationParameters() {
 if (!continuationEnabled.value) return {};
 const parsed = JSON.parse(continuationText.value);
 const state = parsed?.parameters ?? parsed;
 if (!state || Array.isArray(state) || typeof state !== 'object') throw Error('衔接状态须为JSON对象或导出的边界状态文件');
 const unknown = Object.keys(state).filter(key => !continuationKeys.has(key));
 if (unknown.length) throw Error('衔接状态含未知字段 '+unknown.join(', '));
 return state;
}
async function loadContinuation() {
 if (!result.value) return;
 const current = token;
 const recordId = result.value.id;
 try {
  const data = await api('/api/device-dispatch/'+recordId+'/continuation?committed_steps='+(hour.value+1));
  if (current !== token || recordId !== result.value?.id) return;
  continuationText.value = JSON.stringify(data, null, 2);
  continuationEnabled.value = true;
  parameters.value.start = String(data.parameters.start).slice(0,16);
  parameters.value.step_hours = data.parameters.step_hours;
  parameters.value.include_candidates = data.parameters.include_candidates;
  parameters.value.steps = Math.max(1,result.value.result.rows.length-data.committed_steps);
  error.value = '';
 } catch (exception) {
  if (current === token) error.value = String(exception);
 }
}
async function calculate(background=false){commitSettings(false);const current=token,id=props.projectId;busy.value=true;error.value='';result.value=null;try{if(!project.value||!engineering.value?.revision)throw Error('请先保存工程网络与逐设备台账');const continuation=continuationParameters();const input={...parameters.value,...continuation,project_id:id,project_revision:project.value.revision,engineering_revision:engineering.value.revision,grid_available_kw:series(grid.value),initial_energized_nodes:continuationEnabled.value&&continuation.initial_energized_nodes?continuation.initial_energized_nodes:initial.value.trim()?series(initial.value):[],device_availability:keyed(deviceSchedules.value),line_status:keyed(lineSchedules.value)};if(background){const j=await api('/api/study-jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({module:'device_dispatch',parameters:input})});if(current===token){backgroundJob.value=j.id;emit('task',j.id)}return}const d=await api('/api/device-dispatch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});if(current!==token)return;result.value=d;hour.value=0;const h=await api('/api/device-dispatch?project_id='+id);if(current===token)history.value=h}catch(e){if(current===token)error.value=String(e)}finally{if(current===token)busy.value=false}}
async function inspect(id:string){const current=token;try{const d=await api('/api/device-dispatch/'+id);if(current===token&&d.project_id===props.projectId){result.value=d;hour.value=0}}catch(e){if(current===token)error.value=String(e)}}
function download(){const u=URL.createObjectURL(new Blob([JSON.stringify(result.value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='逐设备调度-'+result.value.id.slice(0,8)+'.json';a.click();URL.revokeObjectURL(u)}
async function draw(){const request=++drawToken;await nextTick();if(!chart.value||!result.value){plot?.dispose();plot=undefined;return}const {init}=await import('./chartRuntime');if(request!==drawToken||!chart.value||!result.value)return;plot?.dispose();plot=init(chart.value);const rows=result.value.result.rows;plot.setOption({animation:false,tooltip:{trigger:'axis'},legend:{top:0},grid:{left:70,right:30,top:50,bottom:80},xAxis:{type:'category',data:rows.map((r:any)=>r.timestamp)},yAxis:{type:'value',name:'kW'},dataZoom:[{type:'inside'},{type:'slider'}],series:[['总负荷','load_kw'],['实际供电','served_kw'],['计划削减','controlled_curtailment_kw'],['非计划缺供','shortage_kw'],['外部供电','grid_kw']].map(([name,key])=>({name,type:'line',step:'end',showSymbol:false,data:rows.map((r:any)=>r[key])}))})}
watch(result,draw);const resize=()=>plot?.resize();let chartObserver:ResizeObserver|undefined;watch(chart,element=>{chartObserver?.disconnect();if(element){chartObserver=new ResizeObserver(resize);chartObserver.observe(element)}},{flush:'post'});window.addEventListener('resize',resize);onBeforeUnmount(()=>{++token;++drawToken;chartObserver?.disconnect();plot?.dispose();window.removeEventListener('resize',resize)});
const commitSettings=useParameterTransaction(settingsOpen,{parameters,grid,initial,continuationEnabled,continuationText,deviceSchedules,lineSchedules});
</script>
<template><article><h3>逐设备多节点时序调度</h3><p>本页读取已保存工程网络与台账，使用电源/储能/负荷各自的曲线、接入位置和约束；不自动将旧汇总CSV分配给设备。保存工程或台账后点击“重新读取输入”。</p><p>模型为分层目标MILP与无损LinDistFlow，支持1/5/15/30/60分钟、最长168小时。电气失联分区须有可用构网资源，未初始带电时须具备黑启动条件；本页不提供动态稳定、励磁涌流或真实通信操作结论。</p><p v-if="error" class="error">{{error}}</p><div class="actions"><button @click="refresh" :disabled="busy">重新读取输入</button><span>工程版本 {{project?.revision||'—'}} · 台账版本 {{engineering?.revision||0}} · 电源{{engineering?.inventory.sources.length||0}} / 储能{{engineering?.inventory.storage.length||0}} / 负荷{{engineering?.inventory.loads.length||0}}</span></div><button class="settings-trigger" @click="settingsOpen=true">逐设备调度参数</button><ParameterDialog transactional @apply="commitSettings()" v-model:open="settingsOpen" title="逐设备调度参数"><div class="fields"><label>名称<input v-model="parameters.name" :disabled="busy"></label><label>开始时间<input type="datetime-local" v-model="parameters.start" :disabled="busy"></label><label>时间步长<select v-model.number="parameters.step_hours" :disabled="busy"><option :value="1">60分钟</option><option :value=".5">30分钟</option><option :value=".25">15分钟</option><option :value="5/60">5分钟</option><option :value="1/60">1分钟</option></select></label><label>计算步数<input type="number" min="1" max="672" v-model.number="parameters.steps" :disabled="busy"></label><label>外部无功限额 / kvar<input type="number" min="0" v-model.number="parameters.grid_reactive_limit_kvar" :disabled="busy"></label><label>缺省线路限额 / kVA<input type="number" min="1" v-model.number="parameters.branch_limit_kva" :disabled="busy"></label><label>电压下限 / pu<input type="number" step=".001" v-model.number="parameters.voltage_min_pu" :disabled="busy"></label><label>电压上限 / pu<input type="number" step=".001" v-model.number="parameters.voltage_max_pu" :disabled="busy"></label><label>构网能量预留比例<input type="number" min=".001" max=".5" step=".01" v-model.number="parameters.forming_reserve_ratio" :disabled="busy"></label><label>求解总时限 / s<input type="number" min="1" max="120" v-model.number="parameters.time_limit_seconds" :disabled="busy"></label><label>强制满足台账保供目标<input type="checkbox" v-model="parameters.enforce_load_targets" :disabled="busy"></label><label>允许计划负荷削减<input type="checkbox" v-model="parameters.allow_demand_response" :disabled="busy"></label><label>纳入待建候选设备<input type="checkbox" v-model="parameters.include_candidates" :disabled="busy"></label></div><p>强制保供默认关闭。开启后，禁止中断负荷须每步达标；允许中断负荷受台账最大连续中断时长限制。主动削减低于最低供电比例也计中断；需覆盖完整目标窗口，不可行时不生成供电方案。</p><p>时域 {{parameters.steps*parameters.step_hours}}h。风光水必须在台账中提供可用曲线；空曲线不会按额定出力补造。电源与储能无功能力缺省0，请按设备参数填写；变压器当前只支持变比1的理想支路容量。</p><label class="wide">外部供电容量 / kW（常值或逐步数组，逗号分隔）<input v-model="grid" :disabled="busy"></label><label class="wide">初始已带电节点（可空，逗号分隔；仍须有构网支撑）<input v-model="initial" :disabled="busy"></label>
<details :open="continuationEnabled"><summary>跨窗口状态与可发电量补给</summary>
<label><input type="checkbox" v-model="continuationEnabled" :disabled="busy">使用衔接初态与补给</label>
<p>可粘贴导出的边界状态文件，或填写初态参数对象。勾选后JSON中的start采用后续开始时刻，elapsed_hours采用原事件已逝时长。到位和目标时长从原事件起点计，所有曲线首项对齐本次开始时刻。</p>
<textarea aria-label="跨窗口状态与补给 JSON" v-model="continuationText" rows="12" :disabled="busy" style="width:100%;box-sizing:border-box;font-family:monospace"></textarea>
<p>可发电量补给单位kWh，指定步开始生效，常值表示每步补给。完整目标前史需同时提供尾段、历史最大和累计中断小时，并确认prior_target_history_complete。导出文件含来源归档与版本，请对照本次台账核验。</p>
</details><details><summary>运行成本研究参数</summary><p>以下缺省值仅供调度研究，请按工程核实；不表示地区电价或全寿命经济性。柴油燃料及负荷削减成本读取台账经济参数。</p><div class="fields"><label>购电 / 元/kWh<input type="number" step="any" v-model.number="parameters.grid_energy_yuan_per_kwh" :disabled="busy"></label><label>储能循环 / 元/kWh<input type="number" step="any" v-model.number="parameters.storage_cycle_yuan_per_kwh" :disabled="busy"></label><label>启动 / 元/次<input type="number" step="any" v-model.number="parameters.source_start_cost_yuan" :disabled="busy"></label></div></details><details><summary>设备可用系数与线路断开/恢复</summary><p>可用系数0—1；线路0为断开、1为闭合。填写1个常值或与步数一致的数组，例如4步“0,0,1,1”表示前两步断开后恢复。未配置项按保存状态执行，不自动生成故障概率。</p><h4>设备状态</h4><div v-for="(row,i) in deviceSchedules" :key="i" class="actions"><select v-model="row.id" :disabled="busy"><option v-for="d in devices" :value="d.id">{{d.id}} · {{d.name}}</option></select><input v-model="row.values" :disabled="busy"><button @click="deviceSchedules.splice(i,1)" :disabled="busy">移除</button></div><button @click="deviceSchedules.push({id:devices[0].id,values:'1'})" :disabled="busy||!devices.length">添加设备状态</button><h4>线路状态</h4><div v-for="(row,i) in lineSchedules" :key="i" class="actions"><select v-model.number="row.id" :disabled="busy"><option v-for="l in network?.lines" :value="l.line">线路{{l.line}} · {{l.from_node}} → {{l.to_node}}</option></select><input v-model="row.values" :disabled="busy"><button @click="lineSchedules.splice(i,1)" :disabled="busy">移除</button></div><button @click="lineSchedules.push({id:network.lines[0].line,values:'0'})" :disabled="busy||!network?.lines.length">添加线路状态</button></details><button class="primary" @click="calculate()" :disabled="busy||!engineering?.revision">{{busy?'计算中，请等待…':'执行逐设备调度并归档'}}</button></ParameterDialog></article>
<article v-if="result"><h3>逐设备结果 · {{result.name}}</h3><p>{{statusNames[result.result.status]}} · {{result.result.runtime_seconds.toFixed(3)}}s · {{result.result.variables}}变量 / {{result.result.constraints}}约束。结果为当时保存的工程与台账快照，当前修改不会覆盖。</p><div class="metric-grid"><p>负荷电量 <strong>{{result.result.metrics.load_energy_kwh.toFixed(3)}} kWh</strong></p><p>实际供电 <strong>{{result.result.metrics.served_energy_kwh.toFixed(3)}} kWh</strong></p><p>计划削减 <strong>{{result.result.metrics.controlled_curtailment_energy_kwh.toFixed(3)}} kWh</strong></p><p>非计划缺供 <strong>{{result.result.metrics.shortage_energy_kwh.toFixed(3)}} kWh</strong></p></div><p>分类保供目标：{{statusNames[result.result.metrics.all_load_targets]}}。本窗口起点距事件开始{{result.result.elapsed_hours_at_start??0}}h，完整目标结合已确认前史判定。</p><div ref="chart" class="chart" role="img" aria-label="逐设备供需及缺供曲线"></div><div class="scroll"><table><tr><th>负荷</th><th>类别</th><th>目标时长 / h</th><th>连续目标供电 / h</th><th>最大目标中断 / h</th><th>累计目标中断 / h</th><th>允许连续中断 / h</th><th>供电 / kWh</th><th>计划削减 / kWh</th><th>非计划缺供 / kWh</th><th>目标判定</th></tr><tr v-for="l in result.result.load_metrics" :key="l.id"><td>{{l.name}} · {{l.id}}</td><td>{{l.class}}</td><td>{{l.target_hours}}</td><td>{{l.continuous_target_supply_hours}}</td><td>{{l.maximum_target_interruption_hours}}</td><td>{{l.total_target_interruption_hours??'历史未记录'}}</td><td>{{l.allowed_consecutive_interruption_hours??'历史未记录'}}</td><td>{{l.served_kwh.toFixed(3)}}</td><td>{{l.controlled_curtailment_kwh.toFixed(3)}}</td><td>{{l.shortage_kwh.toFixed(3)}}</td><td>{{statusNames[l.target_status]}}</td></tr></table></div><label class="wide">查看时刻<select v-model.number="hour"><option v-for="(r,i) in result.result.rows" :value="i">{{r.timestamp}}</option></select></label><template v-if="snapshot"><h4>电源出力与燃料</h4><div class="scroll"><table><tr><th>设备</th><th>节点</th><th>运行</th><th>启动指令</th><th>到位上限 / kW</th><th>实际 / kW</th><th>无功 / kvar</th><th>剩余可发电量 / kWh</th></tr><tr v-for="s in snapshot.sources"><td>{{s.id}}</td><td>{{s.node}}</td><td>{{s.on?'是':'否'}}</td><td>{{s.startup_command?'是':'否'}}</td><td>{{s.available_kw.toFixed(3)}}</td><td>{{s.dispatch_kw.toFixed(3)}}</td><td>{{s.reactive_kvar.toFixed(3)}}</td><td>{{s.fuel_remaining_kwh==null?'未设':s.fuel_remaining_kwh.toFixed(3)}}</td></tr></table></div><h4>储能状态</h4><div class="scroll"><table><tr><th>设备</th><th>充电 / kW</th><th>放电 / kW</th><th>期初 / kWh</th><th>期末 / kWh</th><th>SOC</th></tr><tr v-for="b in snapshot.storage"><td>{{b.id}}</td><td>{{b.charge_kw.toFixed(3)}}</td><td>{{b.discharge_kw.toFixed(3)}}</td><td>{{b.energy_begin_kwh.toFixed(3)}}</td><td>{{b.energy_end_kwh.toFixed(3)}}</td><td>{{b.soc==null?'无有效容量':(b.soc*100).toFixed(2)+'%'}}</td></tr></table></div><details><summary>节点电压与支路潮流</summary><table><tr><th>节点</th><th>带电</th><th>线性电压 / pu</th></tr><tr v-for="n in snapshot.nodes"><td>{{n.node}}</td><td>{{n.energized?'是':'否'}}</td><td>{{n.linear_voltage_pu?.toFixed(5)||'未带电'}}</td></tr></table><div class="scroll"><table><tr><th>线路</th><th>闭合</th><th>有功 / kW</th><th>无功 / kvar</th><th>限额 / kVA</th></tr><tr v-for="l in snapshot.lines"><td>{{l.line}}</td><td>{{l.closed?'是':'否'}}</td><td>{{l.p_kw.toFixed(3)}}</td><td>{{l.q_kvar.toFixed(3)}}</td><td>{{l.limit_kva}}</td></tr></table></div></details></template><h4>校核状态与适用范围</h4><p v-for="c in result.result.checks">{{c.name}}：{{statusNames[c.status]}}</p><details><summary>模型与计量口径</summary><p v-for="s in result.result.scope">{{s}}</p></details><div class="actions"><a :href="'/api/device-dispatch/'+result.id+'/csv'">导出逐时CSV</a><button @click="download">导出完整输入与设备结果JSON</button><button @click="loadContinuation" :disabled="busy">载入所选时刻后的衔接状态</button><a :href="'/api/device-dispatch/'+result.id+'/continuation?committed_steps='+(hour+1)">导出所选时刻后的边界状态 JSON</a></div><details><summary>分层求解状态</summary><pre>{{JSON.stringify(result.result.solver,null,2)}}</pre></details></article><article><h3>逐设备调度档案</h3><p v-if="!history.length">当前工程暂无逐设备计算。</p><button v-for="h in history" :key="h.id" @click="inspect(h.id)" class="record">{{h.created}} · {{h.name}} · {{statusNames[h.status]}}</button></article><article><button @click="calculate(true)" :disabled="busy||!engineering?.revision">按当前输入提交后台调度</button><p>后台计算可离开页面，结果保存在“视图 → 计算任务面板”，与原同步调度档案分开。</p></article><button v-if="backgroundJob" @click="emit('task',backgroundJob)">查看当前后台调度任务</button></template>
<style scoped>.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:20px 0}.fields label{display:flex;justify-content:space-between;align-items:center;gap:12px}.fields input,.fields select{width:200px}.fields input[type=checkbox]{width:20px}input,select{padding:8px;border:1px solid #c8dcdf;max-width:100%}.wide{display:flex;gap:16px;align-items:center;margin:15px 0}.wide input{width:430px}.actions{display:flex;gap:14px;flex-wrap:wrap;align-items:center;margin:16px 0}.scroll{overflow:auto;max-height:420px;margin:15px 0}.metric-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.metric-grid strong{display:block;margin-top:10px}.chart{height:370px}.record{display:block;margin:10px 0}.primary{margin:20px 0}details{margin:20px 0}summary{cursor:pointer}pre{white-space:pre-wrap;max-height:350px;overflow:auto}@media(max-width:1000px){.fields{grid-template-columns:1fr}.metric-grid{grid-template-columns:1fr 1fr}}</style>
